# 尝试直接发送原始帧
echo "尝试直接发送原始802.11帧..."
if [ -f /tmp/test_packet.bin ]; then
    # 尝试使用iwpriv或其他工具发送
    iwpriv wlan0 set inject=1 2>/dev/null
    echo "发送测试数据包..."
    # 这里需要实际的帧发送工具
    # 通常需要修改内核才能实现真正的注入
    echo "❌ 直接发送原始帧需要内核级修改"
fi

# 测试3: 尝试不同的注入方法
echo "=== 测试3: 尝试不同的注入方法 ==="

# 方法1: 尝试修改驱动参数
echo "尝试修改驱动参数..."
echo 1 > /sys/module/qca_cld3_peach_v2/parameters/inject 2>/dev/null || echo "inject参数不可用"

# 方法2: 尝试修改WMI服务
echo "尝试修改WMI服务..."
# 需要定位并修改wmi_unified_tlv.c中的服务列表
echo "❌ WMI服务修改需要内核编译"

# 方法3: 尝试内存补丁
echo "尝试内存补丁..."
# 需要定位固件过滤函数并修改
echo "❌ 内存补丁需要内核调试知识"

# 清理
echo "=== 清理测试环境 ==="
ip link set wlan0 down
echo 0 > /sys/module/qca_cld3_peach_v2/parameters/con_mode
ip link set wlan0 up
rm -f /tmp/test_packet.bin

echo "=== 测试完成 ==="
echo "结论: 一加15支持监听模式，但帧注入需要内核级修改"
echo "建议: 如需注入功能，考虑使用OTG外接RTL8188FU适配器"